-- Fakt kartochkalari orqa tomonining ruscha matni — 76-partiya:
-- Sora Eshonto'rayeva, Tavallo, Temur Malik.

UPDATE fact_cards SET detail_ru = 'Сара Абдурахмановна Эшонтураева родилась 8 ноября 1911 года в селении Бешбулак Наманганской области. Источник: Национальная энциклопедия Узбекистана (библиотека Ziyouz.com).' WHERE id = 2330;
UPDATE fact_cards SET detail_ru = 'В 1927 году она окончила узбекскую драматическую студию в Москве. В студии она набралась опыта, играя в таких спектаклях, как «Ревизор», «Принцесса Турандот», «Слуга двух господ». Источник: Национальная энциклопедия Узбекистана (библиотека Ziyouz.com).' WHERE id = 2331;
UPDATE fact_cards SET detail_ru = 'Первые её роли — Турсуной в спектакле «Худжум» и Беатриче в «Слуге двух господ». С 30-х годов она исполняла ведущие главные роли едва ли не во всех сочинениях, поставленных в театре. Источник: Национальная энциклопедия Узбекистана (библиотека Ziyouz.com).' WHERE id = 2332;
UPDATE fact_cards SET detail_ru = 'В 1935 году она снискала славу, создав образ Офелии в спектакле «Гамлет». В энциклопедии написано, что в этой роли она с большой силой выразила трагедию любви. Источник: Национальная энциклопедия Узбекистана (библиотека Ziyouz.com).' WHERE id = 2333;
UPDATE fact_cards SET detail_ru = '«Отелло» был поставлен в 1941 году в театре имени Хамзы, и роль Дездемоны исполнила Сара Эшонтураева. В 1945 году члены парламента Великобритании, посмотрев спектакль, записали в книге почётных гостей, что такого «Отелло» не видели и в Лондоне. Источник: УзА — статья «Отелло в узбекском театре признали и члены парламента Великобритании».' WHERE id = 2334;
UPDATE fact_cards SET detail_ru = 'В её исполнительском обиходе были десятки главных ролей: Онахон («Честь и любовь»), Хуррият («Хуррият»), Катерина («Гроза»), Иокаста («Царь Эдип»). Позже она мастерски создавала и образы матерей, играла роли в кино и в телеспектаклях. Источник: Национальная энциклопедия Узбекистана (библиотека Ziyouz.com).' WHERE id = 2335;
UPDATE fact_cards SET detail_ru = 'Уже в 1937 году она стала народной артисткой Узбекистана и была лауреатом Государственной премии Узбекистана имени Хамзы (1967). Кроме того, в 1946–1955 и 1981–1985 годах она была председателем правления Театрального общества Узбекистана. Источник: Национальная энциклопедия Узбекистана (библиотека Ziyouz.com).' WHERE id = 2336;
UPDATE fact_cards SET detail_ru = 'Сара Эшонтураева умерла 8 сентября 1998 года в Ташкенте. После её смерти, в 2004 году, она была награждена орденом «За великие заслуги». Источник: Национальная энциклопедия Узбекистана (библиотека Ziyouz.com).' WHERE id = 2337;

UPDATE fact_cards SET detail_ru = 'Тавалло (Тулаган Ходжамьяров) родился в 1883 году в ташкентской махалле Оби Назир округа Кукча, в зажиточной семье Ходжамьяра Джиянбаева. «Тавалло» — его литературный псевдоним. Источник: Ziyouz.com, статья Бегали Касимова.' WHERE id = 2338;
UPDATE fact_cards SET detail_ru = 'Тавалло выучился грамоте в школе старого образца, затем получал образование в медресе Бекларбеги и в русско-туземной школе. В поэзии его наставником был Юсуф Сарьями. Источник: Ziyouz.com, статья Бегали Касимова.' WHERE id = 2339;
UPDATE fact_cards SET detail_ru = 'Сборник «Равнак уль-ислам» был напечатан в 1916 году; в нём собрано около семидесяти стихотворений поэта, написанных размером аруз. Это единственная книга, изданная при жизни поэта, и она была переиздана в 1993 году. Источник: Ziyouz.com, статья Бегали Касимова.' WHERE id = 2340;
UPDATE fact_cards SET detail_ru = 'Стихи и статьи Тавалло начали выходить в повременной печати с 1910-х годов под псевдонимом «Тавалло». Выход журнала «Ойна» под редакцией Бехбуди (1913) и газеты «Садои Туркистон» (1914) не остался без внимания поэта. К этому ряду относятся стихи «О любимой Родине», «Обращение к собственной совести и существу», «Обращение к перу». Источник: Ziyouz.com, статья Бегали Касимова.' WHERE id = 2341;
UPDATE fact_cards SET detail_ru = '30 августа 1914 года Тавалло вместе с Мунавваркари, Авлони и другими просвещёнными людьми учредил в Ташкенте товарищество «Нашриёт» для издания книг. Источник: Ziyouz.com, статья Бегали Касимова.' WHERE id = 2342;
UPDATE fact_cards SET detail_ru = '27 февраля 1914 года в ташкентском театре «Колизей» труппа Авлони показала драму Бехбуди «Падаркуш», и Тавалло посвятил этому событию стихотворение. С 1915 года он начал работать в обществе «Турон», созданном по почину Авлони и его соратников. Источник: Ziyouz.com, статья Бегали Касимова.' WHERE id = 2343;
UPDATE fact_cards SET detail_ru = 'Десятки сатирических стихов Тавалло были напечатаны в журнале «Муштум» под подписью «Магзава». В источнике сказано, что эти стихи ещё не собраны и не изучены полностью. Источник: Ziyouz.com, статья Бегали Касимова.' WHERE id = 2344;
UPDATE fact_cards SET detail_ru = '14 августа 1937 года Тавалло был арестован и обвинён в членстве в контрреволюционной организации и в проведении националистических идей в своих стихах. Тройка при НКВД 19 октября 1937 года приговорила его к расстрелу, и приговор был приведён в исполнение 10 ноября. Поэт был оправдан 18 октября 1968 года. Источник: Ziyouz.com, статья Бегали Касимова.' WHERE id = 2345;

UPDATE fact_cards SET detail_ru = 'Год и место рождения Тимура Малика в источниках точно не указаны. Он жил в XIII веке и был известен как правитель Худжандской области. Источник: Ziyouz.com, Миркарим Асим, рассказ «Тимур Малик».' WHERE id = 2346;
UPDATE fact_cards SET detail_ru = 'Тимур Малик был правителем Худжандской области. Во время монгольского нашествия он укрепил крепость посреди реки и решился биться с монголами. Источник: Ziyouz.com, Миркарим Асим, рассказ «Тимур Малик».' WHERE id = 2347;
UPDATE fact_cards SET detail_ru = 'Крепость стояла подле Худжанда, на острове посреди Сырдарьи, которая делила город надвое. Как написано в рассказе, в укреплении были размещены более тысячи витязей и метких стрелков и около сотни корабельных мастеров. Источник: Ziyouz.com, Миркарим Асим, рассказ «Тимур Малик».' WHERE id = 2348;
UPDATE fact_cards SET detail_ru = 'К Худжанду подошло двадцатитысячное монгольское войско под началом нойонов Сокту и Улака. Воины Тимура Малика на судах устраивали внезапные нападения на стан врага; в одном из боёв стрела вонзилась в правый глаз нойона Улака. Источник: Ziyouz.com, Миркарим Асим, рассказ «Тимур Малик».' WHERE id = 2349;
UPDATE fact_cards SET detail_ru = 'Как сказано в рассказе, на готовых судах установили столбы, покрыли их сверху войлоком и обнесли войлоком кругом. Эти суда служили главным средством при обороне островной крепости и при передвижении по реке. Источник: Ziyouz.com, Миркарим Асим, рассказ «Тимур Малик».' WHERE id = 2350;
UPDATE fact_cards SET detail_ru = 'Как написано в рассказе, Тимур Малик, пройдя трудный путь, присоединился к Джалалиддину, бившемуся с монголами на иранской земле, и продолжил борьбу против них. Источник: Ziyouz.com, Миркарим Асим, рассказ «Тимур Малик».' WHERE id = 2351;
UPDATE fact_cards SET detail_ru = 'По рассказу, отступив и добравшись до Хорезма, Тимур Малик собрал там войско, чтобы продолжить битву, и снова двинулся к Сырдарье. Он освободил город Янгикент и, наказав перешедшего к монголам правителя города, поставил на его место другого, преданного человека. Источник: Ziyouz.com, Миркарим Асим, рассказ «Тимур Малик».' WHERE id = 2352;
UPDATE fact_cards SET detail_ru = 'Год смерти Тимура Малика в источниках точно не указан. В рассказе Миркарима Асима изображено, как спустя пятнадцать лет после худжандских событий он в облике дервиша вернулся из Дамаска в свой родной город. Источник: Ziyouz.com, Миркарим Асим, рассказ «Тимур Малик».' WHERE id = 2353;
